BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path=public,extensions;
SELECT plan(10);
INSERT INTO public.tenants(id,name,slug) VALUES ('81000000-0000-0000-0000-000000000001','Requirement test','requirement-test');
INSERT INTO auth.users(id,email) VALUES ('8a000000-0000-0000-0000-000000000001','requirement-test@example.invalid');
UPDATE public.profiles SET tenant_id='81000000-0000-0000-0000-000000000001',is_active=true WHERE id='8a000000-0000-0000-0000-000000000001';
INSERT INTO public.user_roles(user_id,role) VALUES ('8a000000-0000-0000-0000-000000000001','admin');
SET LOCAL "request.jwt.claim.sub"='8a000000-0000-0000-0000-000000000001';
INSERT INTO public.clients(id,name,tenant_id,created_by) VALUES ('8c000000-0000-0000-0000-000000000001','Client','81000000-0000-0000-0000-000000000001','8a000000-0000-0000-0000-000000000001');
INSERT INTO public.vendors(id,name,tenant_id,created_by,contact_email) VALUES ('8d000000-0000-0000-0000-000000000001','Vendor','81000000-0000-0000-0000-000000000001','8a000000-0000-0000-0000-000000000001','shared@example.invalid');
CREATE TEMP TABLE requirement_test_data(id uuid, fields jsonb);
GRANT ALL ON requirement_test_data TO authenticated;
INSERT INTO requirement_test_data(fields) VALUES ('{"title":"Developer","client_id":"8c000000-0000-0000-0000-000000000001","vendor_id":"8d000000-0000-0000-0000-000000000001","vendor_email":"snapshot@example.invalid","vendor_contact":"+13175550188","location":"Dallas, TX","work_mode":"remote","visa_types":["USC"],"rate_type":"hourly","min_experience_years":0,"max_experience_years":5,"primary_technology":"SQL","description":"Description","recruiter_notes":"Notes","duration":"6 months"}');
SELECT ok(NOT has_function_privilege('anon','public.save_requirement(uuid,jsonb,jsonb)','EXECUTE'),'anonymous execution denied');
SELECT ok(NOT (SELECT prosecdef FROM pg_proc WHERE oid='public.save_requirement(uuid,jsonb,jsonb)'::regprocedure),'RLS applies to atomic saves');
SET LOCAL ROLE authenticated;
SET LOCAL "request.jwt.claim.role"='authenticated';
SET LOCAL "request.jwt.claim.sub"='8a000000-0000-0000-0000-000000000001';
UPDATE requirement_test_data SET id=public.save_requirement(NULL,fields,'[{"skill":"SQL"}]');
SELECT is((SELECT vendor_email FROM public.requirements WHERE id=(SELECT id FROM requirement_test_data)),'snapshot@example.invalid','contact snapshot saved');
SELECT is((SELECT contact_email FROM public.vendors WHERE id='8d000000-0000-0000-0000-000000000001'),'shared@example.invalid','shared vendor untouched');
SELECT throws_ok($q$ SELECT public.save_requirement((SELECT id FROM requirement_test_data),'{"title":"Should roll back"}','[{"skill":"Java"},{"skill":"java"}]') $q$,'23505',NULL,'duplicate skill aborts complete save');
SELECT is((SELECT title FROM public.requirements WHERE id=(SELECT id FROM requirement_test_data)),'Developer','parent update rolled back');
SELECT is((SELECT skill FROM public.requirement_skills WHERE requirement_id=(SELECT id FROM requirement_test_data)),'SQL','original skills restored');
SELECT throws_ok($q$ SELECT public.save_requirement((SELECT id FROM requirement_test_data),'{"vendor_contact":""}',NULL) $q$,'22023',NULL,'required contact cannot be cleared');
SELECT throws_ok($q$ SELECT public.save_requirement(NULL,(SELECT fields FROM requirement_test_data),'[{"skill":"SQL"},{"skill":"sql"}]') $q$,'23505',NULL,'failed create is atomic');
SELECT is((SELECT count(*) FROM public.requirements WHERE title='Developer'),1::bigint,'failed create leaves no duplicate parent');
SELECT * FROM finish();
ROLLBACK;
